fn greater(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // We assume `a.len() == b.len()` as per the problem statement.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| (x as i32) > (y as i32))
     .collect()
}

